  "Đặt tiếp": "Tetap pesan",
  "⚠ Kho khu vực thiếu hàng ({a}) — đơn sẽ chờ hàng (Kho xác nhận chờ hàng hoặc từ chối).": "⚠ Gudang area kekurangan stok ({a}) — pesanan akan menunggu barang (Gudang mengonfirmasi menunggu atau menolak).",
  "⚠ Kho khu vực thiếu hàng ({a}) — đơn vào phiếu để chuyển tiền trước; Kế toán xác nhận tiền xong, nếu vẫn thiếu đơn chuyển sang chờ hàng.": "⚠ Gudang area kekurangan stok ({a}) — pesanan masuk nota untuk transfer dulu; setelah Akuntansi konfirmasi, jika masih kurang pesanan pindah ke menunggu barang.",
  "⚠ Vượt trần công nợ — đơn chờ Giám sát khu vực duyệt (nhập mã EO).": "⚠ Melebihi batas utang — pesanan menunggu persetujuan supervisor area (kode EO).",
  "✅ Kho khu vực còn đủ hàng — đơn tự động duyệt và vào phiếu xuất.": "✅ Gudang area stok cukup — pesanan disetujui otomatis dan masuk nota keluar.",
  "✅ Kho khu vực còn đủ hàng — đơn tự động duyệt, vào phiếu chờ chuyển tiền.": "✅ Gudang area stok cukup — pesanan disetujui otomatis, masuk nota menunggu transfer.",
  "✅ Tồn kho của KTV còn đủ — đơn tự động duyệt và vào phiếu xuất.": "✅ Stok teknisi cukup — pesanan disetujui otomatis dan masuk nota keluar.",
  "🔒 Linh kiện đặc thù — đơn chờ TBP DVBH duyệt.": "🔒 Suku cadang khusus — pesanan menunggu persetujuan kepala DVBH.",
  "tự động chuyển đơn của {a} →": "otomatis memindahkan pesanan {a} →",
  "Đơn đang chờ hàng — Kho xác nhận hàng về thì đơn tự duyệt": "Pesanan menunggu barang — disetujui otomatis saat Gudang mengonfirmasi barang tiba",
  "đơn đang chờ hàng — chờ Kho xác nhận hàng về": "pesanan menunggu barang — menunggu konfirmasi Gudang",
  " · dự kiến có hàng {a}": " · perkiraan barang tersedia {a}",
  " · đơn này {a}": " · pesanan ini {a}",
  "Chờ Giám sát duyệt — đơn công nợ vượt trần công nợ của người nhận hàng": "Menunggu persetujuan Supervisor — pesanan utang melebihi batas utang penerima",
  "Chờ TBP DVBH xác nhận — linh kiện thuộc nhóm đặc thù": "Menunggu konfirmasi Kepala Layanan — suku cadang khusus",
  "Chờ Trạm duyệt — đơn do Vệ tinh đặt cần Trạm phụ trách duyệt trước": "Menunggu persetujuan Stasiun — pesanan Satelit harus disetujui Stasiun terlebih dahulu",
  "Chờ hàng — kho công ty khu vực không đủ hàng, đơn chờ Kho xử lý": "Menunggu barang — gudang perusahaan di area ini kurang, sedang ditangani Gudang",
  "Chờ thanh toán — kho công ty khu vực đang thiếu hàng cho đơn này": "Menunggu pembayaran — gudang perusahaan di area ini kekurangan barang untuk pesanan ini",
  "Giám sát khu vực của người nhận hàng duyệt (nhập mã EO) hoặc từ chối.": "Supervisor area penerima menyetujui (memasukkan kode EO) atau menolak.",
  "Giám sát khu vực {a} duyệt (nhập mã EO) hoặc từ chối. Duyệt xong hệ thống tự kiểm tra tồn kho.": "Supervisor area {a} menyetujui (memasukkan kode EO) atau menolak. Setelah disetujui sistem memeriksa stok otomatis.",
  "Hàng về: đơn tự duyệt và vào phiếu xuất kho. Kho từ chối: đơn bị hủy kèm lý do, tiền đã trả (nếu có) về quỹ dư.": "Barang tiba: pesanan disetujui otomatis dan masuk nota pengeluaran. Gudang menolak: pesanan dibatalkan dengan alasan, uang yang dibayar (jika ada) kembali ke dana sisa.",
  "Kho chưa tiếp nhận ticket thiếu hàng.": "Gudang belum menerima tiket kekurangan barang.",
  "Kho đã tiếp nhận{a}{b}.": "Gudang telah menerima{a}{b}.",
  "Khu vực của người nhận hàng chưa có Giám sát — đơn sẽ nằm chờ tới khi Admin gán Giám sát cho khu vực.": "Area penerima belum memiliki Supervisor — pesanan menunggu hingga Admin menetapkan Supervisor untuk area tersebut.",
  "Kế toán xác nhận tiền xong, hệ thống kiểm tra lại kho: đủ hàng thì tự duyệt, vẫn thiếu thì chuyển chờ hàng (đơn giữ số tiền đã trả).": "Setelah Akuntansi mengonfirmasi pembayaran, sistem memeriksa ulang stok: cukup maka disetujui otomatis, masih kurang maka menunggu barang (pesanan menyimpan uang yang dibayar).",
  "Kết quả đặt hàng {id}": "Hasil pemesanan {id}",
  "Lý do:": "Alasan:",
  "TBP duyệt xong, hệ thống tự kiểm tra tồn kho: đủ hàng thì tự duyệt và vào phiếu xuất, thiếu hàng thì chờ hàng / chờ chuyển tiền. TBP từ chối thì đơn bị hủy kèm lý do.": "Setelah Kepala Layanan menyetujui, sistem memeriksa stok: cukup maka disetujui dan masuk nota pengeluaran, kurang maka menunggu barang / pembayaran. Jika ditolak, pesanan dibatalkan dengan alasan.",
  "Theo dõi tiến độ ở danh sách Đơn hàng — mỗi lần đơn đổi trạng thái bạn sẽ nhận thông báo kèm lý do.": "Pantau kemajuan di daftar Pesanan — Anda menerima notifikasi beserta alasan setiap kali status pesanan berubah.",
  "Tiền đã trả cho đơn (nếu có) đã về quỹ dư của người nhận hàng.": "Uang yang dibayar untuk pesanan (jika ada) telah kembali ke dana sisa penerima.",
  "Tiền đã trả cho đơn (nếu có) đã về quỹ dư của người nhận hàng. Cần hàng thì tạo đơn mới theo lý do ở trên.": "Uang yang dibayar untuk pesanan (jika ada) telah kembali ke dana sisa penerima. Jika masih perlu barang, buat pesanan baru dengan memperhatikan alasan di atas.",
  "Trạm duyệt xong, hệ thống tự kiểm tra linh kiện đặc thù, trần công nợ và tồn kho để xử lý tiếp. Trạm từ chối thì đơn bị hủy kèm lý do.": "Setelah Stasiun menyetujui, sistem memeriksa suku cadang khusus, batas utang, dan stok untuk melanjutkan. Jika Stasiun menolak, pesanan dibatalkan dengan alasan.",
