  "Đơn tạo trước khi bật tự động duyệt hoặc được đẩy lại — Tác nghiệp duyệt, từ chối hoặc chuyển chờ hàng.": "Pesanan dibuat sebelum persetujuan otomatis diaktifkan, atau dibuka kembali — Operasional menyetujui, menolak, atau memindahkan ke menunggu barang.",
