  "Người đặt đơn được báo mã EO + ngày dự kiến. Hàng về: Kho bấm \"Hàng đã về\" như thường lệ.": "Pemesan diberi tahu kode EO + tanggal perkiraan. Saat barang datang gudang menekan \"Barang sudah datang\" seperti biasa.",
  "Thông tin để Kho đánh giá": "Informasi untuk penilaian gudang",
  "Ticket chuyển sang Mua hàng đặt hàng (Mua hàng nhận thông báo). Khi Mua hàng báo đã đặt, ticket về chờ hàng về như sau khi Kho tiếp nhận; Kho vẫn xác nhận \"Hàng đã về\".": "Tiket dikirim ke Pembelian untuk dipesan (Pembelian diberi tahu). Setelah dipesan tiket menunggu barang datang seperti setelah diterima gudang; gudang tetap mengonfirmasi \"Barang sudah datang\".",
