  "Tiền cần chuyển của phiếu xuất chứa đơn sẽ giảm tương ứng (tiền đã chuyển thừa về quỹ dư của người nhận).": "Jumlah transfer nota keluar akan berkurang sesuai (kelebihan bayar kembali ke dana lebih penerima).",
  "Xác nhận lưu giá 0đ": "Konfirmasi simpan harga 0",
  "Đơn {a} sẽ có giá trị 0đ — đơn sẽ tự động chuyển trạng thái, KHÔNG còn chờ chuyển tiền nữa.": "Pesanan {a} akan bernilai 0 — statusnya berubah otomatis dan TIDAK lagi menunggu transfer uang.",
  "Đơn đang \"Chờ thanh toán\" vì thiếu hàng: kho đủ hàng thì đơn tự duyệt và vào phiếu xuất; vẫn thiếu thì đơn chuyển \"Chờ hàng\" và mở ticket cho Kho.": "Pesanan \"Menunggu pembayaran\" karena stok kurang: jika stok cukup, pesanan otomatis disetujui dan masuk nota keluar; jika masih kurang, pesanan menjadi \"Menunggu barang\" dan tiket dibuka untuk Gudang.",
  "Cho phép đơn {id} thanh toán sau?\n\nKho đủ hàng → đơn được duyệt và vào phiếu xuất; thiếu hàng → đơn chuyển \"Chờ hàng\" cho Kho xử lý. Tiền vẫn chuyển ở phiếu xuất như đơn bình thường — phiếu không gửi Kế toán được khi chưa chuyển đủ tiền.\n\nGhi chú (không bắt buộc):": "Izinkan pesanan {id} bayar nanti?\n\nJika stok cukup, pesanan disetujui dan masuk nota keluar; jika kurang, pesanan menjadi \"Menunggu barang\" untuk Gudang. Uang tetap ditransfer di nota keluar seperti pesanan biasa — nota tidak bisa dikirim ke Akuntansi sebelum lunas.\n\nCatatan (opsional):",
  "Cho đơn đi tiếp không chờ chuyển tiền — tiền vẫn phải chuyển đủ ở phiếu xuất trước khi gửi Kế toán": "Lanjutkan pesanan tanpa menunggu pembayaran — uang tetap harus lunas di nota keluar sebelum dikirim ke Akuntansi",
  "Thanh toán sau": "Bayar nanti",
  "Đã cho phép bởi {a} · {b}": "Diizinkan oleh {a} · {b}",
  "Đã cho phép thanh toán sau — đơn {a} → {b}": "Bayar nanti diizinkan — pesanan {a} → {b}",
  "⏭ Cho phép thanh toán sau": "⏭ Izinkan bayar nanti",
  "Mã này chưa có linh kiện tương đương nào trong nhóm thay thế (Bảng giá › Linh kiện thay thế).": "Kode ini belum punya suku cadang setara di grup pengganti (Daftar harga › Suku cadang pengganti).",
  "Đơn gốc đang đặt {ma}. Chọn linh kiện tương đương (cùng nhóm thay thế) Kho đang có — đơn đổi sang mã mới (giá theo mã mới), ticket ghi hàng đã về, đơn tự duyệt và vào phiếu xuất kho.": "Pesanan asli untuk {ma}. Pilih suku cadang setara (grup pengganti yang sama) yang tersedia di gudang — pesanan beralih ke kode baru (harga kode baru), tiket dicatat barang tiba, dan pesanan otomatis disetujui masuk ke nota keluar.",
  "Đổi LK tương đương": "Ganti suku cadang setara",
  "Kho từ chối bắt buộc nhập lý do": "Penolakan gudang wajib mengisi alasan",
  "Lý do từ chối (bắt buộc, áp dụng cho {a} dòng đã chọn — KTV nhận được lý do này):": "Alasan penolakan (wajib, berlaku untuk {a} baris terpilih — teknisi menerima alasan ini):",
  "Rút lại xác nhận \"Đã chuyển\" để sửa / hủy ảnh bằng chứng? Phiếu về \"Chờ KTV chuyển\" cho tới khi bấm \"Đã chuyển\" lại.": "Tarik kembali konfirmasi \"Sudah transfer\" untuk memperbaiki / menghapus foto bukti? Nota kembali ke \"Menunggu teknisi transfer\" sampai Anda menekan \"Sudah transfer\" lagi.",
  "Up nhầm ảnh — rút lại để sửa / hủy ảnh bằng chứng (trước khi Kế toán duyệt)": "Salah unggah foto — tarik kembali untuk memperbaiki / menghapus foto bukti (sebelum Akuntansi menyetujui)",
  "Đã rút lại xác nhận — bỏ ảnh sai (✕), thêm ảnh đúng rồi bấm \"Đã chuyển\" lại": "Konfirmasi ditarik — hapus foto yang salah (✕), tambah foto yang benar lalu tekan \"Sudah transfer\" lagi",
