  "Đối tác cho đơn \"MUA HÀNG CÔNG NỢ ĐỐI TÁC\" — giá niêm yết, không cần chuyển khoản. Công nợ hiện tại = Ban đầu + Đã ghi nợ (phiếu Kế toán đã chốt) + Đơn đang chờ − Đã thanh toán; vượt mốc tối đa thì đơn chờ Giám sát duyệt. KTV có Mã MISA trùng đối tác được tự đặt cho chính mình.": "Mitra untuk pesanan \"MUA HÀNG CÔNG NỢ ĐỐI TÁC\" — harga daftar, tanpa transfer. Utang saat ini = Awal + Tercatat (slip diselesaikan Akuntansi) + Pesanan tertunda − Dibayar; melebihi batas maksimum, pesanan menunggu persetujuan Supervisor. Teknisi dengan kode MISA sama dengan mitra boleh memesan untuk dirinya sendiri.",
