  "Đơn vượt mốc công nợ đối tác — đã được duyệt": "Pesanan melebihi batas kredit mitra — disetujui",
  "Đơn vượt trần công nợ — đã được duyệt": "Pesanan melebihi batas kredit — disetujui",
  "Đơn đang nằm trong phiếu chưa gửi Kế toán sẽ rời phiếu và mang theo tiền đã thanh toán. Ticket thiếu hàng mở ở bước “Chờ mua hàng” để bạn nhập mã EO + ngày dự kiến; Kho xác nhận hàng về như thường. KTV không tự hủy được đơn khi ticket đang xử lý.": "Pesanan di slip yang belum dikirim ke Akuntansi akan keluar dari slip dan membawa uang yang sudah dibayar. Tiket kekurangan dibuka di tahap “Menunggu pembelian” agar Anda mengisi kode EO + tanggal perkiraan; Gudang mengonfirmasi barang datang seperti biasa. Teknisi tidak dapat membatalkan saat tiket diproses.",
  "Đơn đang soạn chưa được tạo. Bạn có muốn lưu lại thông tin này cho lần sau không?": "Pesanan yang sedang dibuat belum dibuat. Simpan untuk lain kali?",
