  "Chưa có hướng dẫn nào. Bấm \"Thêm hướng dẫn\" để soạn câu trả lời mẫu cho các thắc mắc KTV hay hỏi.": "Belum ada panduan. Klik \"Tambah panduan\" untuk menulis jawaban contoh bagi pertanyaan yang sering diajukan teknisi.",
