  "Hướng dẫn hiện ngay khi KTV mở khung Hỏi đáp; khi KTV gõ câu hỏi app tự gợi ý, gửi câu hỏi thì hệ thống tự trả lời bằng hướng dẫn khớp nhất. Ảnh tự tải lên Google Drive.": "Panduan tampil saat teknisi membuka Tanya jawab; saat mengetik, aplikasi menyarankan panduan, dan setelah pertanyaan dikirim sistem otomatis menjawab dengan panduan paling cocok. Gambar otomatis diunggah ke Google Drive.",
