  "Hủy yêu cầu": "Batalkan permintaan",
  "KTV nộp {a}": "Setoran teknisi {a}",
  "KTV tự nộp": "Setoran teknisi",
  "KTV tự nộp tiền vào quỹ kèm ảnh chuyển khoản. Kế toán đối chiếu sao kê rồi xác nhận số thực nhận — tiền vào quỹ và tự trừ cho phiếu đang chờ chuyển tiền.": "Teknisi menyetor uang ke dana dengan bukti transfer. Akuntansi mencocokkan mutasi rekening lalu mengonfirmasi jumlah diterima — uang masuk dana dan dipotong untuk slip yang menunggu pembayaran.",
  "Khoản đã hủy": "Entri dibatalkan",
  "Kế toán đã hủy khoản tiền này ở “Tiền ngoài vào quỹ” — tiền đã trừ lại khỏi quỹ.": "Akuntansi membatalkan entri ini di “Uang luar ke dana” — jumlahnya sudah dikurangi lagi dari dana.",
  "Ngày chuyển": "Tanggal transfer",
