  "Tiền chỉ vào quỹ sau khi Kế toán đối chiếu sao kê và xác nhận. Bạn sẽ nhận thông báo kết quả.": "Uang baru masuk dana setelah Akuntansi mencocokkan mutasi dan mengonfirmasi. Anda akan menerima notifikasi hasilnya.",
  "Trùng số tiền với khoản gần đây của cùng quỹ (30 ngày): {a} — kiểm tra sao kê, tránh ghi 1 lần chuyển 2 lần.": "Jumlah sama dengan entri terbaru dana yang sama (30 hari): {a} — periksa mutasi agar 1 transfer tidak dicatat 2 kali.",
