  "Hệ thống sẽ kiểm tra lại đơn theo loại mới:": "Sistem akan memeriksa ulang pesanan dengan jenis baru:",
  "Kho / Mua hàng đã tiếp nhận chờ hàng — không đổi loại đề xuất được": "Gudang / Pembelian sudah menerima tiket menunggu stok — jenis usulan tidak dapat diubah",
  "Khác nhóm loại đề xuất của phiếu đang chứa đơn → đơn tự rời phiếu và vào phiếu phù hợp hoặc phiếu mới; giá / chiết khấu tính lại.": "Berbeda kelompok jenis dengan slip saat ini → pesanan keluar dari slip dan masuk slip yang sesuai atau slip baru; harga / diskon dihitung ulang.",
  "Không đổi qua lại với loại TRẢ HÀNG ở đây — TN dùng nút Sửa đơn": "Tidak dapat beralih ke/dari jenis RETUR di sini — Operasional memakai Ubah pesanan",
  "Không đổi được loại đề xuất: ": "Gagal mengubah jenis usulan: ",
