  "Phiếu xuất của đơn đã chuyển tiền / Kế toán đã duyệt tiền — không đổi được": "Slip keluar pesanan sudah ada transfer / Akuntansi sudah menyetujui uang — tidak dapat diubah",
  "Phiếu xuất của đơn đã gửi Kế toán / Kho — không đổi được": "Slip keluar pesanan sudah dikirim ke Akuntansi / Gudang — tidak dapat diubah",
  "Tồn kho được xét lại: đủ hàng → duyệt; thiếu → chờ chuyển tiền hoặc chờ hàng.": "Stok diperiksa ulang: cukup → disetujui; kurang → menunggu pembayaran atau stok.",
  "Vượt trần công nợ → chờ Giám sát duyệt; linh kiện đặc thù cần TBP → chờ TBP xác nhận.": "Melebihi batas utang → menunggu persetujuan Supervisor; suku cadang khusus → menunggu konfirmasi kepala bagian.",
