  "Bỏ chọn = chỉ tách đơn, cả 2 đơn vẫn chờ hàng.": "Hapus centang = hanya pisah, kedua pesanan tetap menunggu stok.",
  "Các phiếu này chưa được Kế toán chốt xong đơn xuất nên giá trị được cộng vào mức chiết khấu của đơn đặt mới — đặt thêm trước khi Kế toán chốt để hưởng chiết khấu cao hơn.": "Slip ini belum difinalkan Akuntansi, jadi nilainya dihitung ke tingkat diskon pesanan baru — pesan lebih banyak sebelum Akuntansi memfinalkan untuk diskon lebih tinggi.",
  "Hàng về ít hơn số lượng đặt? Tách phần đã về sang đơn mới (duyệt vào phiếu, chuyển Kế toán), phần còn thiếu tiếp tục chờ Kho.": "Barang datang kurang dari pesanan? Pisahkan bagian yang datang ke pesanan baru (disetujui ke slip, dikirim ke Akuntansi); sisanya tetap menunggu Gudang.",
  "Kho có {a}/{b}": "Stok {a}/{b}",
  "Kho công ty chỉ đủ một phần — hệ thống dừng tự duyệt hàng về cho mã này, chờ Kho / Kế toán chọn phương án (tách đơn hoặc chờ đủ).": "Stok perusahaan hanya cukup sebagian — persetujuan otomatis untuk kode ini dihentikan, menunggu Gudang / Akuntansi memilih (pisah pesanan atau tunggu stok penuh).",
  "Kho công ty hiện có {a}/{b} chiếc cho đơn này. Đơn đang được ưu tiên nên hệ thống DỪNG tự duyệt hàng về cho mã này (kể cả đơn xếp sau) — chọn phương án: tách phần đã có để giao trước, hoặc giữ chờ đủ hàng.": "Stok perusahaan ada {a}/{b} unit untuk pesanan ini. Pesanan ini prioritas, jadi sistem MENGHENTIKAN persetujuan otomatis untuk kode ini (termasuk pesanan berikutnya) — pilih: pisahkan untuk mengirim yang tersedia dulu, atau tunggu stok penuh.",
