  "Linh kiện còn thiếu để xử lý đơn bảo hành — do app Sửa chữa bảo hành gửi sang khi đơn chậm vì không có linh kiện / hết hàng tồn kho. Mỗi bước xử lý được báo ngay về đơn bảo hành gốc.": "Suku cadang yang masih kurang untuk pekerjaan garansi — dikirim aplikasi Perbaikan Garansi saat pekerjaan tertunda karena tidak ada suku cadang / stok habis. Setiap langkah langsung dilaporkan ke pekerjaan garansi asal.",
