  "\"Khách hàng đã chuyển khoản về công ty\" chỉ áp dụng cho đơn mua (có tiền thanh toán)": "\"Pelanggan sudah transfer ke perusahaan\" hanya untuk pesanan pembelian (ada pembayaran)",
  "1 phiếu chỉ gom đơn cùng hình thức xuất hóa đơn (Không / HĐ - Không thu phí / HĐ - Có thu phí / HĐ - Xuất cho trạm) và cùng loại \"KH đã chuyển khoản về công ty\"": "Satu slip hanya untuk pesanan dengan jenis faktur yang sama (Tidak / Faktur - tanpa biaya / Faktur - dengan biaya / Faktur - untuk stasiun) dan tanda \"pelanggan sudah transfer\" yang sama",
  "Chọn 1 hình thức xuất hóa đơn (đơn mua) để tích.": "Pilih jenis faktur (pesanan pembelian) untuk mencentang.",
  "KH chuyển khoản về công ty": "Pelanggan transfer ke perusahaan",
  "Khách hàng đã chuyển khoản về công ty": "Pelanggan sudah transfer ke perusahaan",
  "Phiếu có YÊU CẦU XUẤT HÓA ĐƠN": "Slip MEMERLUKAN FAKTUR",
  "Phiếu có yêu cầu xuất hóa đơn: {a}": "Slip memerlukan faktur: {a}",
  "Quỹ KH chuyển khoản": "Dana transfer pelanggan",
  "Tiền Kế toán xác nhận vào Quỹ KH chuyển khoản (không vào quỹ của KTV); đơn chỉ dùng tiền trong quỹ này.": "Uang yang dikonfirmasi Akuntansi masuk dana faktur pelanggan (bukan dana teknisi); pesanan hanya memakai dana ini.",
  "Tiền vào Quỹ KH chuyển khoản, không vào quỹ của KTV": "Uang masuk dana faktur pelanggan, bukan dana teknisi",
  "tiền xác nhận vào Quỹ KH chuyển khoản (không vào quỹ của KTV).": "uang yang dikonfirmasi masuk dana faktur pelanggan (bukan dana teknisi).",
  "Đơn KH chuyển khoản đã có tiền trong Quỹ KH chuyển khoản — chưa hỗ trợ gán sang KH lẻ": "Pesanan transfer pelanggan sudah ada uang di dana faktur pelanggan — belum bisa dialihkan ke pelanggan eceran",
  "Đơn khác hình thức xuất hóa đơn (hoặc khác \"KH đã chuyển khoản về công ty\") với phiếu này — mỗi hình thức 1 phiếu riêng": "Jenis faktur pesanan (atau tanda \"pelanggan sudah transfer\") berbeda dengan slip ini — tiap jenis punya slip sendiri",
  "Đơn tích \"Khách hàng đã chuyển khoản về công ty\" phải chọn 1 hình thức xuất hóa đơn": "Pesanan bertanda \"Pelanggan sudah transfer ke perusahaan\" harus memilih jenis faktur",
  "Đơn đang nằm trong phiếu đã gửi Kế toán — không đổi được hình thức xuất hóa đơn (phiếu tách theo hình thức hóa đơn)": "Pesanan ada di slip yang sudah dikirim ke Akuntansi — jenis faktur tidak bisa diubah (slip dipisah per jenis faktur)",
  "— Kế toán lưu ý xuất hóa đơn cho phiếu này.": "— Akuntansi: harap terbitkan faktur untuk slip ini.",
  "Còn phải chuyển (phiếu KH)": "Masih harus ditransfer (slip pelanggan)",
  "Khoản chuyển tiền KH": "Transfer pelanggan",
  "Số dư theo KTV": "Saldo per teknisi",
  "Sổ quỹ KH": "Buku dana pelanggan",
  "Tiền khách hàng chuyển khoản về công ty cho đơn có yêu cầu xuất hóa đơn. Quỹ gắn theo KTV nhận hàng nhưng TÁCH RIÊNG quỹ cá nhân của KTV: chỉ trả cho phiếu KH chuyển khoản; đơn hủy / từ chối thì tiền về lại quỹ này.": "Uang yang ditransfer pelanggan ke perusahaan untuk pesanan dengan faktur. Dana milik teknisi penerima tetapi TERPISAH dari dana pribadi teknisi: hanya membayar slip transfer pelanggan; pesanan batal / ditolak mengembalikan uang ke dana ini.",
  "Tất cả KTV": "Semua teknisi",
  "Tồn quỹ KH chuyển": "Saldo dana transfer pelanggan",
  "{a} KTV đang có tồn": "{a} teknisi memiliki saldo",
  "Hoàn tiền cho KH": "Pengembalian ke pelanggan",
  "(không ghi lý do)": "(tanpa alasan)",
  "Bằng chứng chuyển tiền của bạn bị trả lại. Kế toán CHƯA ghi nhận số tiền này — hàng sẽ chưa được xuất cho tới khi bạn chuyển lại / bổ sung đúng.": "Bukti transfer Anda dikembalikan. Akuntansi BELUM mencatat jumlah ini — barang tidak dikirim sampai Anda transfer ulang / melengkapi dengan benar.",
  "Bỏ {n} đơn khỏi phiếu": "Hapus {n} pesanan dari slip",
  "Chuyển tiền ngay →": "Transfer sekarang →",
  "KTV này đang có phiếu cùng loại đề xuất nhưng THIẾU HÀNG, đang tách riêng:": "Teknisi ini punya slip jenis permintaan sama yang KEKURANGAN STOK, dipisahkan:",
  "Kiểm tra lại số tiền, tài khoản nhận, nội dung chuyển khoản theo lý do trên.": "Periksa jumlah, rekening penerima dan keterangan transfer sesuai alasan di atas.",
  "Lưu ý Kế toán": "Catatan untuk Akuntansi",
  "Mở phiếu → bỏ ảnh sai, tải ảnh chuyển khoản đúng (hoặc chuyển bổ sung phần còn thiếu) → bấm \"Đã chuyển\" để gửi Kế toán xác nhận lại.": "Buka slip → hapus gambar salah, unggah bukti transfer yang benar (atau transfer kekurangannya) → tekan \"Sudah transfer\" untuk dikirim ulang ke Akuntansi.",
  "Phiếu chờ hàng": "Slip menunggu stok",
  "Phiếu chờ hàng — tách riêng đơn kho thiếu hàng, đơn có hàng nằm ở phiếu khác": "Slip menunggu stok — pesanan kekurangan stok dipisah, pesanan tersedia ada di slip lain",
  "Quỹ dư của {a} còn": "Sisa dana {a}:",
  "Quỹ KH chuyển khoản còn": "Sisa dana faktur transfer pelanggan:",
  "Tách {n} đơn kho thiếu hàng ra 1 phiếu chờ hàng riêng?\n\nPhiếu này chỉ còn đơn có hàng để Kế toán xuất trước. Tiền cần chuyển được tính lại cho từng phiếu (phần đã chuyển thừa về quỹ và tự trừ cho phiếu kia).": "Pindahkan {n} pesanan kekurangan stok ke slip menunggu stok terpisah?\n\nSlip ini hanya berisi pesanan tersedia agar Akuntansi mengirim lebih dulu. Jumlah dihitung ulang per slip (kelebihan bayar masuk dana dan dipotong untuk slip lain).",
  "Tách {n} đơn thành 1 phiếu mới": "Pisahkan {n} pesanan ke 1 slip baru",
