  "{n} phiếu của bạn bị trả lại bằng chứng chuyển tiền. Kế toán CHƯA ghi nhận số tiền này — hàng sẽ chưa được xuất cho tới khi bạn chuyển lại / bổ sung đúng.": "{n} slip Anda dikembalikan bukti transfernya. Akuntansi BELUM mencatat jumlah ini — barang tidak dikirim sampai Anda transfer ulang / melengkapi dengan benar.",
