  "— các đơn đã chọn vào chung 1 phiếu mới của cùng KTV (vd để xuất sau), tiền cần chuyển tính lại cho từng phiếu.": "— pesanan terpilih masuk 1 slip baru teknisi yang sama (mis. dikirim nanti); jumlah dihitung ulang per slip.",
