  "— tiền đã thanh toán của các đơn = 0. Tổng phiếu giảm, phần đã trả thừa hoàn về quỹ dư của KTV.": "— jumlah dibayar pesanan ini = 0. Total slip turun; kelebihan bayar kembali ke saldo teknisi.",
