  "Các khoản đã vào quỹ của {a} trong 180 ngày (chuyển tiền phiếu, nộp tiền, tiền ngoài). Khoản cùng số tiền với 1 ảnh hoặc ảnh giống (màu + bố cục) xếp lên đầu. Bấm ảnh để xem lớn.": "Dana yang masuk ke dana {a} dalam 180 hari (transfer slip, setoran, dana luar). Entri dengan nominal sama dengan salah satu gambar atau gambar mirip (warna + tata letak) ditampilkan paling atas. Klik gambar untuk memperbesar.",
