  "Hạn tính theo GIỜ LÀM VIỆC từ lúc đơn / phiếu vào bước (T2–T6 08:00–12:00, 13:00–17:00; T7 08:00–12:00; CN nghỉ). Bật “Giờ lịch 24/7” để tính liên tục cả ngoài giờ. Đổi cấu hình chỉ áp cho ca ghi nhận sau đó. Hệ thống tự quét mỗi giờ.": "Batas waktu dihitung dalam JAM KERJA sejak pesanan / slip masuk langkah (Sen–Jum 08:00–12:00, 13:00–17:00; Sab 08:00–12:00; Min libur). Aktifkan “Jam kalender 24/7” untuk menghitung terus-menerus. Perubahan hanya berlaku untuk kasus yang dicatat sesudahnya. Sistem memindai setiap jam.",
